-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con la categoria fauna y la columna drops).
--
-- Enemigos de Genshin Impact: los 569 del archivo del juego, divididos en
-- jefes (61), esbirros (285, de los que 80 son elites) y fauna (223).
--
-- Fuentes:
--   Yatta (gi.yatta.moe) -> nombre y descripcion oficiales en espanol e ingles,
--     faccion, resistencias, botin, consejos de combate e imagen.
--   Datos del propio juego (AnimeGameData, de Dimbreath) -> rango.
--
-- En Genshin no hay debilidades como en Honkai: cada enemigo tiene una
-- resistencia a cada elemento (normalmente 10%). En weaknesses van los
-- elementos con resistencia negativa, y en resistances las ocho, con las
-- inmunidades marcadas. Las versiones con resistencias distintas (Abismo,
-- eventos...) quedan en variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 4 de 4 (112 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('gi-enemy-28042002', 'genshin-impact', 'Lumpo níveo cremabatida', 'Cream Snowfin', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de Snezhnaya que tiene un cuerpo completamente redondeado y, aunque a primera vista parece un pariente lejano de los peces globo que habitan por todo Teyvat, en realidad pertenece a un linaje totalmente distinto. Cuando el Gremio de Pescadores lo registró por primera vez, recibió el nombre provisional de “lumpo de las nieves”. Tras más de diez generaciones de pescadores, el uso popular acabó abreviando su nombre a “lumpo níveo”.
El lumpo níveo cremabatida, de color casi completamente blanco y extremadamente escaso, es considerado uno de los peces más preciados de Snezhnaya. Cuenta la leyenda que, si la calidad del agua en la que vive empeora aunque sea un poco, su cuerpo comienza a adquirir otros colores. Incluso protagoniza varios cuentos infantiles sobre un joven pescador prodigio que sigue a uno de estos peces hasta el fantástico reino de la crema batida. Estas historias llegaron a ser tan populares que, durante un tiempo, la crema batida se agotó en toda la ciudad.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131055.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28042003', 'genshin-impact', 'Lumpo níveo lunar', 'Moonlight Snowfin', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de Snezhnaya que tiene un cuerpo completamente redondeado y, aunque a primera vista parece un pariente lejano de los peces globo que habitan por todo Teyvat, en realidad pertenece a un linaje totalmente distinto. Cuando el Gremio de Pescadores lo registró por primera vez, recibió el nombre provisional de “lumpo de las nieves”. Tras más de diez generaciones de pescadores, el uso popular acabó abreviando su nombre a “lumpo níveo”.
Según las leyendas populares, el lumpo níveo lunar es la variedad de pez de Snezhnaya con mayor resistencia y mejor sentido de la orientación. Se dice que sus antepasados viajaron hasta las aguas de Nod Krai y que, tras bañarse bajo la luz de la luna, adquirieron ese peculiar color. Sin embargo, los comerciantes que regresaron de Nod Krai desmintieron esta historia, mientras que los biólogos señalan que probablemente se deba a las plantas acuáticas de las que suele alimentarse. Aun así, como el apelativo “lunar” suena bien y es fácil de recordar, el nombre ha perdurado hasta nuestros días.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131056.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28050105', 'genshin-impact', 'Mariposa coralina', 'Coral Butterfly', 'fauna', 'normal', 'Otros', 'El patrón migratorio de los pólipos de coral se parece al de las mariposas.
Cuando están por completar la transformación de una desenfrenada energía elemental de un área, los restos de la siguiente generación de pólipos de coral se condensan en forma de alas que revolotean por Enkanomiya en busca del próximo lugar donde vivir y reproducirse.
Aunque son los destructores del antiguo orden y solo pueden vivir en la oscuridad del océano, el dios serpiente les dio otra oportunidad.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Wisp_Tokoyo_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040902', 'genshin-impact', 'Marlín de jade', 'Halcyon Jade Axe Marlin', 'fauna', 'normal', 'Animales acuáticos', 'Pariente lejano del pez mariposa, este pez posee un esqueleto de gran tamaño y forma curvilínea. Cuenta la leyenda que el primer pescador que atrapó uno de estos peces lo hizo enganchando la caña al extremo de la aleta caudal de pez, y descubrió así que la forma resultante se parecía a la de una lanza. De ahí que este pez se denomine lanza jadeíta. En comparación con su nombre científico, gancho de mariposa, esta denominación resulta más llamativa, por lo que se ha extendido entre la gente de a pie.
Al lanza jadeíta le gusta vivir en entornos con un exuberante lecho marino y sus tonalidades esmeraldas se camuflan con el entorno. Con frecuencia, los peces más pequeños que se mueven por el fondo marino, se topan con sus cuerpos camuflados y se desorientan. Sin embargo, el lanza jadeíta no se lo toma como una provocación. Al contrario, suele ofrecer cobijo y protección a otros peces.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131028.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040901', 'genshin-impact', 'Marlín lanceolado', 'Lazurite Axe Marlin', 'fauna', 'normal', 'Animales acuáticos', 'Pariente lejano del pez mariposa, este pez posee un esqueleto de gran tamaño y forma curvilínea. Cuenta la leyenda que el primer pescador que atrapó uno de estos peces lo hizo enganchando la caña al extremo de la aleta caudal de pez, y descubrió así que la forma resultante se parecía a la de una lanza. De ahí que este pez se denomine lanza alada. En comparación con su nombre científico, gancho de mariposa, esta denominación resulta más llamativa, por lo que se ha extendido entre la gente de a pie.
Aunque lleva el nombre de un arma y su poder supera al de muchas otras especies, la mayor parte de estos animales son realmente mansos, sobre todo el lanza alada de franjas añil y dorado. Gracias a la dureza de sus escamas, el lanza alada puede defenderse de cualquier ataque de otras criaturas acuáticas, por lo que puede marcharse tranquilamente una vez que su oponente se ha quedado sin fuerzas.
Su fuerza supone un desafío hasta para los maestros pescadores. La única forma de pescar al marlín lanceolado es enfrentarse a él como si fuera una poderosa bestia marina y aguantar hasta que se agote su resistencia.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131027.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041501', 'genshin-impact', 'Mecanismo Fuentenigma - Patrullero', 'Secret Source Scout Sweeper', 'fauna', 'normal', 'Animales acuáticos', 'Un pequeño y ágil mecanismo con forma de pez. Parece compartir la misma tecnología que los mecanismos de las ruinas antiguas y tiene la facultad de moverse fácilmente en un medio líquido, incluido el flogisto líquido de alta temperatura. También puede ser que esté diseñado para detectar fuentes de calor de forma autónoma, ya que tiende a acercarse automáticamente a las fuentes térmicas.
Debido a este instinto que tienen de ir en búsqueda del calor, los pescadores expertos pueden usar cebos que emitan calor para atraparlos. Al desmontarlos, se puede obtener extraños dispositivos de una civilización antigua, motivo por el cual estos Mecapeces son muy valiosos.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131045.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041105', 'genshin-impact', 'Mecarreparador - Líder áureo', 'Maintenance Mek: Gold Leader', 'fauna', 'normal', 'Animales acuáticos', 'Meca auxiliar compacto que se desarrolló para ayudar a los Mecabots submarinos a aumentar la tasa de asistencia al trabajo general del equipo. Originalmente, se diseñó para eliminar los residuos submarinos, como basura y restos vegetales, y así evitar que se adhirieran a las partes clave de los Mecabots, minimizando la tasa de fallos de estos. Visto de otro modo, no cabe duda de que también desempeñan el papel de “limpiadores submarinos”, lo cual es beneficioso para el entorno ecológico de Fontaine.
En comparación con otros modelos fabricados en serie, este particular mecarreparador líder áureo presenta una carcasa de color dorado claro y un dispositivo de control especial. El equipo de desarrollo concibió este mecarreparador como una “estación de mando de transmisión” de alto rendimiento que recibiría y distribuiría diversas órdenes a los mecarreparadores circundantes cuando operasen en terrenos submarinos complejos, lo que lo convierte en todo un “líder” indispensable.
Sin embargo, con la suspensión del proyecto de los mecarreparadores, estos “mecas líderes” han perdido su importancia, salvo por su reconocible aspecto de color dorado claro, lo que los hace tener un gran valor de colección a ojos de algunos pescadores.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131036.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041103', 'genshin-impact', 'Mecarreparador de control', 'Maintenance Mek: Situation Controller', 'fauna', 'normal', 'Animales acuáticos', 'Un Mecabot que ayuda en tareas submarinas y mejora el rendimiento de la maquinaria de submarinismo. Originalmente, servía para limpiar basura, algas y otros desechos a fin de evitar la obstrucción de los componentes de los Mecabots acuáticos y, así, minimizar los errores. Es por ello que se los considera “basureros subacuáticos” y son tan importantes para el ecosistema de Fontaine.
Este Mecabot cuenta con un sensor que detecta cualquier objetivo y analiza la basura que encuentra con su “olfato”. Por eso, a veces también se sienten atraídos por los cebos que lanzan los pescadores al agua. Los que han conseguido atrapar uno con su caña suelen denominarlo “mecarreparador acuático” o “mecapez”.
En ciertas circunstancias, los mecarreparadores confunden el alimento de criaturas acuáticas con basura, lo que da lugar a desencuentros de los que los mecanismos más pequeños no salen muy bien parados. Por ello, poco después, la población de mecarreparadores se redujo drásticamente.
Para proteger a los dos anteriores modelos, los investigadores se basaron en el marco científico disponible para aumentar el rendimiento de la estructura central y, así, desarrollar un nuevo tercer modelo con capacidad de combate que expulsara a esas criaturas acuáticas. Así garantizaría un buen entorno de trabajo para los mecarreparadores y se podrían seguir produciendo en masa.
Sin embargo, más tarde, el Instituto de Ciencias de Fontaine ordenó que se detuviera el desarrollo de estos mecarreparadores de control porque “Si estos cacharros ahuyentan a los seres acuáticos más feroces, ¡¿para qué vamos a necesitar a los anteriores mecanismos subacuáticos?!”. Además, hay pruebas que demuestran que los mecarreparadores de control no pueden ahuyentar a los seres más peligrosos, sino que solamente se encargan de algunos peces comunes y, además, impactan negativamente en el medio ambiente. Por ello, los investigadores tuvieron que apagar algunos y restringir sus funciones de ataque.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131034.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041101', 'genshin-impact', 'Mecarreparador de función básica', 'Maintenance Mek: Initial Configuration', 'fauna', 'normal', 'Animales acuáticos', 'Un Mecabot que ayuda en tareas submarinas y mejora el rendimiento de la maquinaria de submarinismo. Originalmente, servía para limpiar basura, algas y otros desechos a fin de evitar la obstrucción de los componentes de los Mecabots acuáticos y, así, minimizar los errores. Es por ello que se los considera “basureros subacuáticos” y son tan importantes para el ecosistema de Fontaine.
Este Mecabot cuenta con un sensor que detecta cualquier objetivo y analiza la basura que encuentra con su “olfato”. Por eso, a veces también se sienten atraídos por los cebos que lanzan los pescadores al agua. Los que han conseguido atrapar uno con su caña suelen denominarlo “mecarreparador acuático” o “mecapez”.
Los primeros modelos de mecarreparadores están hechos a base de finas capas de madera y minerales de relativo bajo coste. La primera tanda de modelos estaba equipada con un dispositivo de movilidad enfocada directamente a cumplir con sus objetivos. Sin embargo, su funcionamiento distaba mucho de lo deseado. Por eso, se implementó un modelo de trabajo por turnos, de forma que cuando algunos de estos mecarreparadores completaban sus tareas o quedaban inutilizados por algún motivo, otra tanda de mecapeces que permanecían ocultos en el fondo marino los reemplazaban de inmediato, garantizando así la continuidad de las tareas de limpieza submarina. Por ello, la mayor parte de la gente piensa que se trata de mecanismos capaces incluso de reproducirse, pues surgen de la nada en un instante. Así que no te sientas culpable si pescas uno o dos sin darte cuenta.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131032.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041104', 'genshin-impact', 'Mecarreparador dorado de coleccionismo', 'Maintenance Mek: Platinum Collection', 'fauna', 'normal', 'Animales acuáticos', 'Un Mecabot que ayuda en tareas submarinas y mejora el rendimiento de la maquinaria de submarinismo. Originalmente, servía para limpiar basura, algas y otros deshechos a fin de evitar la obstrucción de los componentes de los Mecabots acuáticos y, así, minimizar los errores.
Comparado con otros modelos producidos en masa, este mecarreparador dorado de coleccionismo posee una cubierta más limpia y brillante. Se trata de un modelo conmemorativo producido por un equipo de desarrolladores que, para convencer a unos comerciantes adinerados de que financiaran su proyecto, les regalaron estos modelos conmemorativos para que los colocaran en sus peceras como sofisticados peces ornamentales. Por desgracia, todos los intentos del equipo para captar inversiones fracasaron, así que decidieron vender estos mecarreparadores como juguetes para sufragar los gastos cada vez más cuantiosos del proyecto.
Al final, todo el mundo acabó enterándose de lo ocurrido, así que el equipo de desarrolladores detuvo su trabajo y se cancelaron los proyectos futuros. Actualmente, nadie se encarga de ningún mecarreparador que vive en las aguas de Fontaine, y el lote del modelo dorado de coleccionismo cuya producción se realizó con antelación acabó en el fondo del agua, en paradero desconocido y siendo la especie piscícola más distintiva y cara de Fontaine. Conforme se hacían públicos algunos proyectos del Instituto de Ciencias, los periodistas de «El Pájaro de Vapor» empezaron a investigar y contrastar información, y descubrieron que “la contaminación acuática de Fontaine no experimentó grandes mejoras incluso tras el despliegue de los mecarreparadores, por lo que dicho proyecto ha tenido una eficacia dudosa”. Más tarde, los mecarreparadores dorados de colección que aún no habían sido activados siguieron patrullando las aguas de Fontaine, y los pescadores empezaron a alardear cuando pescaban uno, ya que eran con diferencia mucho menos comunes que los peces ornamentales de otras naciones.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131035.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041102', 'genshin-impact', 'Mecarreparador purificaaguas', 'Maintenance Mek: Water Body Cleaner', 'fauna', 'normal', 'Animales acuáticos', 'Un Mecabot que ayuda en tareas submarinas y mejora el rendimiento de la maquinaria de submarinismo. Originalmente, servía para limpiar basura, algas y otros desechos a fin de evitar la obstrucción de los componentes de los Mecabots acuáticos y, así, minimizar los errores. Es por ello que se los considera “basureros subacuáticos” y son tan importantes para el ecosistema de Fontaine.
Este Mecabot cuenta con un sensor que detecta cualquier objetivo y analiza la basura que encuentra con su “olfato”. Por eso, a veces también se sienten atraídos por los cebos que lanzan los pescadores al agua. Los que han conseguido atrapar uno con su caña suelen denominarlo “mecarreparador acuático” o “mecapez”.
Comparado con el modelo de mecarreparador de función básica, el cual ha sido masivamente distribuido, este modelo purificaaguas más pulido y producido en masa cuenta con una potente capa anticorrosiva. Además, el investigador a cargo de desarrollar este mecanismo no empleó un sistema de transporte de descarga inmediata y no adoptó medidas de descarga desfavorables, sino que utilizó un diseño de recuperación y reparación periódicos. De esta forma, los investigadores pueden usar destellos de cierta frecuencia para enviar señales de navegación al sensor de este mecarreparador y, así, lograr que regresen para repararlos, examinarlos y volver a soltarlos en el agua para que sigan trabajando. Al final, esos destellos se acabaron convirtiendo en un cebo específico para mecarreparadores y, de alguna forma desconocida, se popularizaron entre los pescadores.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131033.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040201', 'genshin-impact', 'Medaka', 'Medaka', 'fauna', 'normal', 'Animales acuáticos', 'Un pez energético y de pequeño tamaño conocido por su aspecto de flor.
Solían vivir sus vidas en paz como peces ornamentales, pero desde que se descubrió que su carne es sabrosa, con pocas espinas y mucha grasa, son preparados cuidadosamente y servidos en la mesa.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131000.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040204', 'genshin-impact', 'Medaka azul', 'Aizen Medaka', 'fauna', 'normal', 'Animales acuáticos', 'Un pez energético y de pequeño tamaño conocido por su aspecto de flor.
Hace mucho tiempo, se decía en broma que para conseguir medakas azules solo tenías que meter medakas normales en un bote de tinte azul. En origen, esto debió ocurrírsele a un niño con una imaginación desbordante, pero dio pie a la aparición de muchos vendedores de pescado sin escrúpulos. A su vez, esto provocó conversaciones del tipo “¿Soy yo o este pescado está destiñendo?”. Como respuesta, el Ministerio de Asuntos Civiles colgó este aviso específico: “Compradores, no se dejen engañar: un medaka azul no se puede encontrar todos los días”.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131003.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040202', 'genshin-impact', 'Medaka brillante', 'Glaze Medaka', 'fauna', 'normal', 'Animales acuáticos', 'Un pez energético y de pequeño tamaño conocido por su aspecto de flor.
Esta especie tiene unos patrones de comportamiento impredecibles y a menudo empiezan a moverse con dificultad de repente, como si les doliera algo. No obstante, este fenómeno nunca ocurre cuando están solos, por lo que algunos investigadores creen que esta peculiaridad se debe a su deseo innato de actuar.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131001.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040203', 'genshin-impact', 'Medaka dulce', 'Sweet-Flower Medaka', 'fauna', 'normal', 'Animales acuáticos', 'Un pez energético y de pequeño tamaño conocido por su aspecto de flor.
Estos peces son muy golosos y cada parte de su cuerpo parece ser un radar para buscar dulces. Recorren cada arroyo y cada río de Teyvat buscando golosinas y nunca dicen que no a nada, aunque estén enganchados a un anzuelo. Si pones un cebo, ellos lo morderán.
Fáciles de atrapar incluso para pescadores principiantes.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131002.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041901', 'genshin-impact', 'Medusa brillolunar', 'Moonglow Jellyfish', 'fauna', 'normal', 'Otros', 'Un animal primitivo de composición extremadamente simple.
En los antiguos poemas de Fontaine, las medusas y las mariposas solían ser consideradas un símbolo del alma. Tanto el pueblo de antaño como los filósofos de Remuria compartían la misma idea: que el alma habita en el cuerpo, igual que las mariposas salen de las crisálidas de las orugas, y que el alma fluye eternamente por todas las aguas y la serenata, igual que una medusa se otorga a sí misma una nueva vida en el momento de su muerte.
No obstante, cabe mencionar que los seguidores de la Maestra de Todas las Aguas, conocidos posteriormente como los ilustres y nobles Caballeros Aguapura, condenaron categóricamente las ideas de los filósofos de Remuria, las cuales tacharon de heréticas y afirmaron que debían dejar de existir. En cuanto a qué diferencia había entre esas ideas y las suyas, se trata de un asunto que incumbe unos fundamentos más profundos y no es algo que deba discutirse a la ligera.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_JellyFish_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020313', 'genshin-impact', 'Micóquero', 'Shroomboar', 'fauna', 'normal', 'Animales terrestres', 'Un jabalí salvaje que habita en la selva. Parece mantener algún tipo de peculiar relación de simbiosis con los hongos en desarrollo de la zona.
Según los investigadores, los micóqueros dependen del camuflaje natural de los hongos para defenderse de depredadores y poder vivir plácidamente en la jungla. Por desgracia, eso también lo convierte en uno de los alimentos favoritos a la mesa.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Boar_Grass.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030203', 'genshin-impact', 'Milano lapis', 'Lapis Glede', 'fauna', 'normal', 'Aves', 'Un milano altivo y de vista aguda.
Un ave rapaz que anida entre las cimas rocosas de las montañas. A la gente le gusta decir que estas aves siempre están surcando las nubes y no se posan nunca, pero esa creencia es el producto de la ignorancia y el romanticismo. ¡Hasta los milanos lapis necesitan llevarse algo al pico y proteger a sus polluelos!', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Falcon_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030712', 'genshin-impact', 'Mochuelo nocturno', 'Nochhornowl', 'fauna', 'normal', 'Aves', 'Un ave que habita en Snezhnaya, cubierta por completo de un plumaje como la noche. Su nombre se debe a su costumbre de ir de caza una vez que ya se ha puesto el sol.
Como el depredador más astuto del cielo de las llanuras nevadas, el mochuelo nocturno es un experto en camuflarse, observar y atacar por sorpresa.
Muchos cazadores lo consideran un símbolo de sabiduría. Creen que posee una gran inteligencia y lo respetan como iguales. A cambio, el mochuelo nocturno a veces se convierte en el guía de los cazadores y les comunica mensajes de las profundidades del bosque.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Owl_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28050301', 'genshin-impact', 'Mosca brillofortuna', 'Lucklight Fly', 'fauna', 'normal', 'Otros', 'Una criatura inofensiva capaz de absorber la energía de las misteriosas piedras del subsuelo de la Sima y de emitir un tenue brillo. Este brillo es muy apreciado por los mineros, pues lo consideran una señal de buen augurio, de ahí que la llamaran “mosca brillofortuna”.
Todo el mundo cuida de ellas debido al brillo que aportan en la oscuridad.
Tras desenterrar unas “cosas extrañas” en la Sima, su población creció exponencialmente.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Boltbug_Lightbug_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28050302', 'genshin-impact', 'Mosca brillojade', 'Malachitin Lumibug', 'fauna', 'normal', 'Otros', 'Una particular criatura que sobrevive gracias a la débil energía remanente que extrae del jade.
Cuando está quieta, algunos aventureros la confunden con un jade, de ahí su nombre.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Boltbug_Lightbug_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021201', 'genshin-impact', 'Nutria apacible', 'Leisurely Otter', 'fauna', 'normal', 'Animales terrestres', 'Una particular forma de vida que vive en el agua. Al parecer, guarda cierta relación biológica con los tejones que viven en la superficie. Es mansa y apacible por naturaleza y lleva un estilo de vida muy relajado, casi como si no tuviera ningún tipo de preocupación.
Es frecuente encontrarla recostada en el agua, mientras se deja mecer por las corrientes con las dos patas unidas sobre el vientre como si estuviera dándole la bienvenida a alguien. Sin embargo, bajo esa apariencia impasible se esconde una criatura inteligente capaz de aprovechar los riscos y salientes de las rocas para abrir caracolas y moluscos de los que se alimenta. En ocasiones, tras una copiosa comida, se sienten tan llenos que pueden pasar mucho tiempo sin tener que volver a buscar alimento. Es lo que se llama “reposar después de una comilona”.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Beaver_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28070701', 'genshin-impact', 'Orca aletaescarcha', 'Frostfin Whale', 'fauna', 'normal', 'Animales acuáticos', 'Para la mayor parte de los animales, las orcas aletaescarcha son fieras depredadoras... pero no es así para los humanos.
Su enorme aleta caudal podría hacer naufragar fácilmente a los barcos pesqueros, y podría devorar a un humano de un bocado, pero todos los pescadores saben que las orcas aletaescarcha nunca atacan a los humanos sin provocación. Al contrario, les encanta competir en carreras contra los barcos y suelen saltar por encima del agua, como si disfrutaran jugando con los humanos.
Dicen que hay quienes han esperado durante horas en un barco tiritando de frío con tal de poder vislumbrar siquiera a una de estas criaturas saltando. Pero ¿quién iba a resistirse a la sonrisa de uno de estos animales tan poderosos y hermosos?', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Orca_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28070801', 'genshin-impact', 'Orca aletaescarcha brillolunar', 'Moonglow Frostfin Whale', 'fauna', 'normal', 'Animales acuáticos', 'Una extraordinaria criatura acuática que se ha transformado debido a los efectos del kuuvahki.
Según las investigaciones realizadas hace quinientos años por el biólogo de Snezhnaya Hvilyolo Verjratski, generalmente hablando, la concentración de kuuvahki de la superficie no sería suficiente para inducir cambios morfológicos en criaturas de semejante envergadura. Quizás por esa misma razón, a los raros ejemplares de distinta coloración se les haya dotado de una simbología más romántica. En el folclore de Nod Krai se dice que, si alguien ve una orca aletaescarcha rosa, sus deseos se cumplirán. En ciertas versiones de «La leyenda del gran ladrón Reed Miller», existe una historia en la que el llamado “rey de las orcas” ayudó al ladrón y a sus alegres compañeros a vencer al cautivador canto de las sirenas, e incluso hizo que la reina de las sirenas se enamorara del ladrón a primera vista.
Sin embargo, las historias absurdas siguen siendo solamente historias, igual que una orca no deja de ser, simplemente, una orca.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Orca_01_Alter.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021701', 'genshin-impact', 'Oso ártico', 'Polyarbear', 'fauna', 'normal', 'Animales terrestres', 'Un animal capaz de sobrevivir incluso en climas de frío extremo, dotado de un cuerpo enorme y un pelaje grueso.
A pesar de su gran tamaño, el oso ártico es sorprendentemente ágil, ya que puede saltar entre témpanos de hielo y es experto en rastrear a sus presas sin hacer el menor ruido. Se podría decir que es el cazador más formidable de las tierras heladas.
El oso ártico, un luchador nato, jamás es dócil ni se somete fácilmente ante otros animales o humanos. Por ello, en algunas regiones de Snezhnaya, la gente lo considera un símbolo de fuerza.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Bear_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[]}]'::jsonb, '[]'::jsonb, null),
  ('gi-enemy-28030313', 'genshin-impact', 'Pájaro crepuscular', 'Dusk Bird', 'fauna', 'normal', 'Aves', 'Un pájaro que vive en los bosques de Sumeru. Causa sensación allá donde va por sus vívidos colores. Si se domestica, puede servir como ave mensajera.
Se dice que antaño el pájaro crepuscular poseía cierta inteligencia y era capaz de imitar la lengua de las personas e incluso comprender mensajes escritos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_Beak.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030303', 'genshin-impact', 'Paloma alagrís', 'Graywing Pigeon', 'fauna', 'normal', 'Aves', 'Un ave muy común en Teyvat. Aunque suelen ser regordetas, pueden adiestrarse para enviar mensajes.
Una paloma corriente que se llama así por sus alas grises. Estas aves lucen en el cuello un bonito color esmeralda que cambia de tono, pero como son tan comunes, muy pocos se fijan en su hermoso plumaje.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030305', 'genshin-impact', 'Paloma azabache', 'Black King Pigeon', 'fauna', 'normal', 'Aves', 'Un ave muy común en Teyvat. Aunque suelen ser regordetas, pueden adiestrarse para enviar mensajes.
Una paloma bastante corriente cuyo nombre proviene de su cabeza negra. Son más valientes y agresivas que las demás palomas, y más fáciles de atrapar. Su carne es firme y sabrosa, ideal para cocinar a la parrilla.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_05.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030301', 'genshin-impact', 'Paloma blanca', 'White Pigeon', 'fauna', 'normal', 'Aves', 'Un ave muy común en Teyvat. Aunque suelen ser regordetas, pueden utilizarse para enviar mensajes.
Las palomas blancas son amistosas con los humanos, pero son muy sensibles a las malas intenciones. Una anécdota interesante: se rumorea que la forma más auténtica de preparar el pollo asado con miel de Mondstadt es utilizando carne de paloma. Pero esto es solo un rumor sin fundamento, obviamente.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030304', 'genshin-impact', 'Paloma carmesí', 'Crimsonflank Pigeon', 'fauna', 'normal', 'Aves', 'Un ave muy común en Teyvat. Aunque suelen ser regordetas, pueden adiestrarse para enviar mensajes.
Estas palomas viven en áreas montañosas y sus plumas se han teñido del color rojizo de las rocas y la tierra, lo que les confiere un aspecto muy elegante.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_04.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030302', 'genshin-impact', 'Paloma coronada', 'Brightcrown Pigeon', 'fauna', 'normal', 'Aves', 'Un ave muy común en Teyvat. Aunque suelen ser regordetas, pueden adiestrarse para enviar mensajes.
Una paloma corriente que se llama así por el brillo lustroso de su cabeza. Como es un pájaro tan común, muy pocos se fijan en su hermoso plumaje.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Pigeon_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030704', 'genshin-impact', 'Paragüero anaranjado', 'Burgundy Umbrellafinch', 'fauna', 'normal', 'Aves', 'Un pequeño y rechoncho pájaro, familia lejana del pinzón de Fontaine. Su nombre le fue dado por la forma de paraguas que tienen las llamativas plumas que le adornan la cabeza.
Las investigaciones demuestran que el paragüero anaranjado no es precisamente un habilidoso volador, lo que le convierte en presa fácil para todo tipo de depredadores. Sin embargo, es capaz de usar su plumaje naranjado para camuflarse haciéndose pasar por una planta o roca y evitar así cualquier ataque.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Eggplant_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030703', 'genshin-impact', 'Paragüero cenizazul', 'Slate Umbrellafinch', 'fauna', 'normal', 'Aves', 'Un pequeño y rechoncho pájaro, familia lejana del pinzón de Fontaine. Su nombre le fue dado por la forma de paraguas que tienen las llamativas plumas que le adornan la cabeza.
Las investigaciones sugieren que el paragüero cenizazul tiene una forma física sorprendente, pese a lo que sugiere su apariencia, y que son capaces de planear enormes distancias. Su plumaje ceniciento le sirve de camuflaje cuando sobrevuela los cielos o cuando se pasea cerca del agua, convirtiéndolo en una presa difícil para sus depredadores.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Eggplant_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030603', 'genshin-impact', 'Pelícano picopúrpura', 'Redbill Pelican', 'fauna', 'normal', 'Aves', 'Un ave acuática que vive en zonas acuáticas abiertas, como ríos y lagos, y cuyas características más destacables son su pico de color púrpura y sus hermosas plumas.
Como los pelícanos son unas excelentes aves pesqueras gracias a su aguda vista, los pescadores de muchos sitios, entre los que se incluye la Aldea Chiaoying, los domestican para que los ayuden en sus labores. Algunos pescadores más veteranos hasta consideran que “un pelícano bien entrenado vale más que diez aprendices que no dan pie con bola”, pues el primero no se caerá al agua mientras rema y no espantará a los peces.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Uka_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041001', 'genshin-impact', 'Perca aletacorazón', 'Rippling Heartfeather Bass', 'fauna', 'normal', 'Animales acuáticos', 'Un extraño pez que de lado parece tener la forma de un corazón, de ahí su nombre de “aletacorazón”. Por lo que se cuenta, guarda cierta relación biológica con la perca. Sus aletas dorsal y pélvica están formadas por estrechos huesos que se asemejan a unas plumas.
Al tratarse de una de las variedades más importantes de percas aletacorazón, este pez posee una asombrosa capacidad de remonte, incluso contra el fuerte oleaje. Al parecer, cuando salen a la superficie, se sirven de sus aletas pélvicas, que emiten un sonido parecido a un “plas, plas”. Distinguir a este pez turquesa entre las olas es de por sí misión imposible, por lo que muchos pescadores ni siquiera han llegado a escuchar este sonido.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131030.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041002', 'genshin-impact', 'Perca ascuacorazón', 'Blazing Heartfeather Bass', 'fauna', 'normal', 'Animales acuáticos', 'Un extraño pez que de lado parece tener la forma de un corazón, de ahí su nombre de “perca corazón”. Por lo que se cuenta, guarda cierta relación biológica con la perca. Sus aletas dorsal y pélvica están formadas por estrechos huesos que se asemejan a unas plumas.
La perca ascuacorazón posee unas particulares tonalidades que resultan especialmente llamativas bajo el agua. Se rumorea que es una especie de método de protección, pues el resto de las criaturas marinas la identifica como “un objeto ardiente no identificado” y tienden a alejarse de ella. Sin embargo, pese a su apariencia, la perca ascuacorazón posee una temperatura corporal relativamente baja, por lo que suele pasearse por aguas poco profundas deliberadamente para tomar el sol.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131031.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040102', 'genshin-impact', 'Perca de lomo azul', 'Blue-Fin Bass', 'fauna', 'normal', 'Animales acuáticos', 'Un pez muy común que puede encontrarse por todas partes. Su carne es muy apreciada y es un ingrediente en muchos platos de pescado de Teyvat.
La perca de lomo azul tiene una carne más tierna que sus parientes de lomo negro, y por eso es más popular entre los paladares refinados.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fish_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040103', 'genshin-impact', 'Perca de lomo dorado', 'Golden Bass', 'fauna', 'normal', 'Animales acuáticos', 'Un pez muy común que puede encontrarse por todas partes. Su carne es muy apreciada y es un ingrediente en muchos platos de pescado de Teyvat.
La perca de lomo dorado es mucho menos común que la perca de lomo negro o azul. Se dice que pescar una trae buena suerte.
En los mercados de Liyue se solían vender talismanes y tarjetas de bendición con la forma de percas de lomo dorado; y en Inazuma se decía que el sol del ocaso era como una perca dorada nadando por el cielo.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fish_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040101', 'genshin-impact', 'Perca de lomo negro', 'Black-Back Bass', 'fauna', 'normal', 'Animales acuáticos', 'Un pez muy común que puede encontrarse por todas partes. Su carne es muy apreciada y es un ingrediente en muchos platos de pescado de Teyvat.
La perca de lomo negro es una de las especies acuáticas más abundantes en Teyvat. Se dice que, cuanto más oscuro es su lomo, mayor es la edad de la perca. Los pescadores veteranos pueden distinguir a simple vista las buenas capturas simplemente por el color de sus escamas.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fish_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041003', 'genshin-impact', 'Perca jadecorazón', 'Jade Heartfeather Bass', 'fauna', 'normal', 'Animales acuáticos', 'Se dice que este peculiar pez de perfil acorazonado tiene cierta relación biológica con la perca. Además, sus aletas dorsal y ventral plumosas formadas por cartílagos alargados han hecho que los estudiosos lo bauticen con el nombre de “perca corazón”.
El color de la perca jadecorazón es especialmente característico, pues se asemeja al del jade en el agua, de ahí su nombre. Posee una fuerte vitalidad que no se corresponde con su tranquila apariencia y es capaz de sobrevivir en aguas de diferentes características. La calidad del agua, clara y limpia, del Valle Chenyu le resulta ideal. Allí, su bello nombre de jade es ampliamente conocido, y vive llevando una vida despreocupada, sana y cómoda.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131037.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020414', 'genshin-impact', 'Perro de las nieves', 'Morozhound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo del ser humano!
Los perros de las nieves poseen una resistencia asombrosa y un temperamento dócil, por lo que los humanos les ataron arneses para que tiraran de trineos, con lo que formaron los primeros equipos de transporte de las llanuras nevadas.
Hoy en día, los trineos tirados por perros son más bien una atracción turística de los pueblos fronterizos y un deporte competitivo con el que algunas personas rinden homenaje a sus tradiciones. Aun así, los habitantes de las llanuras nevadas siguen considerando a los perros de las nieves como sus compañeros más cercanos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_SledDog_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040504', 'genshin-impact', 'Pez ángel', 'Abiding Angelfish', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie de pez mariposa muy poco común y apreciada. En la actualidad solo se puede encontrar en masas de agua cercanas a las moradas de los Adeptus. Tiene unas rayas blancas muy hermosas y vive más tiempo que sus parientes de otras especies, por lo que se considera un pez de la suerte bendecido por los Adeptus.
Mucha gente de Liyue se niega a comer este pez por principios, debido al respeto que inspiran los Adeptus, pero otros no creen en las supersticiones y aseguran que comer este pez alarga la esperanza de vida.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131016.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040505', 'genshin-impact', 'Pez ángel raimei', 'Raimei Angelfish', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie de pez mariposa muy poco común y apreciada que vive en Inazuma. Le encantan las masas de agua imbuidas del elemento Electro y las corrientes eléctricas.
Se dice que estos peces provenían de la misma línea que los peces ángel de Liyue hasta que unos comerciantes itinerantes los exportaron a Inazuma. Allí, sus patrones de comportamiento experimentaron un cambio inesperado. En la actualidad, algunos investigadores los utilizan junto con Slimes Electro para sus experimentos.
“No siento la lengua”, dijo cierto gourmet avaricioso tras probar un plato hecho con pez ángel raimei.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131017.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041202', 'genshin-impact', 'Pez buzotorrencial', 'Diving Rapidfighting Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un anfibio que se llama “pez”, pero que en realidad no lo es. Tiene una cabeza plana con forma de daga, como si estuviera preparado para luchar en cualquier momento contra sus depredadores. Sin embargo, en realidad es muy dócil y no se le da bien combatir, de modo que su cabeza le es útil para reducir la resistencia del agua al nadar en ríos. Gracias a ello, es capaz de nadar velozmente contra rápidos torrentes de agua, de ahí que su nombre sea “pez torrencial”.
Estos peces torrenciales azulados son capaces de bucear a gran profundidad, pero no permanecen mucho tiempo en el fondo marino porque les gusta sentir la calidez de los rayos del sol y jugar con Crías de Koholasaurio.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131039.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28042103', 'genshin-impact', 'Pez copoestrella iridiscente', 'Iridescent Starbloom Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez singular que habita en las aguas de Snezhnaya. Visto de frente, sus seis aletas forman una figura parecida a una estrella y a un copo de nieve, por lo que el primer pescador que lo descubrió lo llamó “pez copoestrella”. Las escamas de la subespecie azul poseen una textura y un color extraordinarios y, bajo cierta iluminación, parecen cristales que reflejan un arcoíris, de ahí el elegante apelativo “iridocristalino”. Gracias a su deslumbrante aspecto, el pez copoestrella iridiscente se ha convertido en uno de los ejemplares más codiciados por los coleccionistas de peces de Snezhnaya. Algunos incluso construyen costosos acuarios especialmente para ellos, solo para después pasar muchísimo tiempo sin conseguir pescar ni uno...', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131059.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28042101', 'genshin-impact', 'Pez copoestrella rojidulce', 'Ruby Starbloom Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez singular que habita en las aguas de Snezhnaya. Visto de frente, sus seis aletas forman una figura parecida a una estrella y a un copo de nieve, por lo que el primer pescador que lo descubrió lo llamó “pez copoestrella”. La subespecie roja presenta un color similar al de la remolacha roja, de ahí el apelativo “rojidulce”. Sin embargo, este nombre solo hace referencia a su aspecto. Algunos eruditos descubrieron que la coloración de su cuerpo sirve principalmente para intimidar a ciertos depredadores y protegerse. Curiosamente, a ojos de los humanos, esto solo consigue que parezca aún más apetecible.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131057.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28042102', 'genshin-impact', 'Pez copoestrella turquesafeérico', 'Frostpetal Starbloom Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez singular que habita en las aguas de Snezhnaya. Visto de frente, sus seis aletas forman una figura parecida a una estrella y a un copo de nieve, por lo que el primer pescador que lo descubrió lo llamó “pez copoestrella”. La subespecie turquesa presenta un color similar al de los bordes de los pétalos de la flor frigifeérica, de ahí el apelativo “turquesafeérico”. En comparación con otras variedades de su especie, el pez copoestrella turquesafeérico posee sentidos muy agudos y es capaz de detectar el peligro desde lejos para luego huir a toda velocidad gracias al impulso de sus seis aletas.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131058.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040206', 'genshin-impact', 'Pez de cristal', 'Crystalfish', 'fauna', 'normal', 'Animales acuáticos', 'Un tipo de medaka poco común que reluce como el cristal. Los patrones dibujados en sus escamas son muy intrincados, por lo que algunos lo llaman “pez artista”.
Algunos mercaderes aseguran que estos peces ponen una perla de cristal en ciertas condiciones extremas, y que esta perla es muy valiosa y un signo de calidad. Por este motivo, todo el mundo quiere comprar estos peces y su precio subió como la espuma. Pero los pescadores conocen la verdad: ese objeto no es más que una perla de locha que el pez se comió por accidente y que los vendedores de pescado le hacen escupir cuando les conviene.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131005.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041201', 'genshin-impact', 'Pez floratorrencial', 'Floral Rapidfighting Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un anfibio que se llama “pez”, pero que en realidad no lo es. Tiene una cabeza plana con forma de daga, como si estuviera preparado para luchar en cualquier momento contra sus depredadores. Sin embargo, en realidad es muy dócil y no se le da bien combatir, de modo que su cabeza le es útil para reducir la resistencia del agua al nadar en ríos. Gracias a ello, es capaz de nadar velozmente contra rápidos torrentes de agua, de ahí que su nombre sea “pez torrencial”.
Como estos rosados peces torrenciales tienen el prefijo “flora” en su nombre, algunos turistas piensan que están relacionados con la Tribu Plumaflora o los Qucusaurios. Dicen que ese color rosado les aporta un camuflaje perfecto para evitar a sus depredadores en zonas marinas poco profundas con rocas de colores marrones y rojizas.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131038.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040601', 'genshin-impact', 'Pez globo', 'Pufferfish', 'fauna', 'normal', 'Animales acuáticos', 'Las aletas cortas y redondeadas, el cuerpo rechoncho y el rostro dócil es lo primero que se ve al mirar a un pez globo. Su apariencia es un fiel reflejo de su carácter apagado, lento y perezoso. Sin embargo, no muchos saben que su apariencia torpe oculta una habilidad impresionante: este pez es capaz de absorber agua en su cuerpo y después expulsarla por la boca en forma de un potente chorro, con tanta fuerza y puntería que hasta los pescadores se quedan aturdidos.
“Si te encuentras en una zona de peces globo, ten cuidado con los escupitajos”, dice el capítulo sobre los peces globo del «Manual de pesca con caña».', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131019.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040602', 'genshin-impact', 'Pez globo amargo', 'Bitter Pufferfish', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie de pez globo poco común. Como su propio nombre indica, esta criatura esparce amargor donde quiera que vaya. Su chorro de agua es más lento y más pequeño que el de sus parientes, pero su poder de ataque es comparable gracias a las feromonas excepcionalmente amargas que contiene el agua que escupe. Durante la fase de cortejo se puede ver a los machos y las hembras lanzándose chorros mutuamente. Tal vez compartir las amarguras de la vida también es una manifestación de amor.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131020.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040803', 'genshin-impact', 'Pez globo arenisco', 'Sandstorm Angler', 'fauna', 'normal', 'Animales acuáticos', 'Un pez redondo con una característica estructura cartilaginosa en forma de cuerno. Se dice que este tipo de peces utilizan dichos cartílagos para cavar cuevas subacuáticas, crear sus propias madrigueras, o defenderse de posibles depredadores.
Este espécimen de color ocre no resulta especialmente llamativo a simple vista, pero ha resultado ser de gran importancia. Su anatomía fue esencial a la hora de investigar las cualidades ecológicas de esta especie de animales acuáticos. Este tipo de peces poseen una descomunal fuerza y sus cuernos son los más resistentes de toda la especie, lo que le permite actuar como el trabajador acuático más diligente de todos. Como resultado de sus actividades a lo largo de los años en los lechos de los ríos y los fondos de los lagos, adoptaron esa especial tonalidad ambarina que les sirve también de protección.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131025.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040804', 'genshin-impact', 'Pez globo crepuscular', 'Sunset Cloud Angler', 'fauna', 'normal', 'Animales acuáticos', 'Un pez redondo con una característica estructura cartilaginosa en forma de cuerno. Se dice que este tipo de peces utilizan dichos cartílagos para cavar cuevas subacuáticas, crear sus propias madrigueras, o defenderse de posibles depredadores.
Es el espécimen más longevo de todos y es fácil de distinguir por el tono rosa apagado de su cuerpo, que recuerda al color del crepúsculo justo antes del anochecer. Este color tan distintivo radica de su particular forma de supervivencia. La piel de estos peces tiene una composición parecida a la de la bilis, por lo que su sabor resulta extremadamente amargo. De ahí que el resto de criaturas marinas prefieran guardar las distancias.
Sin embargo, si se cocina adecuadamente, ese regusto amargo puede dar lugar a todo un paladar de deliciosos sabores. Por ello, es uno de los productos favoritos en cualquier mercado. En los puestos de Sumeru a menudo se ven carteles que dicen: “No se debe criar al pez globo crepuscular junto a otros peces comestibles”.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131026.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040801', 'genshin-impact', 'Pez globo imberbe', 'True Fruit Angler', 'fauna', 'normal', 'Animales acuáticos', 'Un pez globo con una característica estructura cartilaginosa en forma de cuerno. Se dice que este tipo de peces utilizan dichos cartílagos para cavar cuevas subacuáticas, crear sus propias madrigueras, y defenderse de posibles depredadores.
El color verdoso de su cuerpo es particularmente común dentro de esta especie de animales acuáticos. Dicho color se asemeja al de la fruta poco madura, por lo que también se les conoce como “imberbes”.
Al contrario de lo que cabría esperar, estos peces tienen pocas espinas y mucha carne. Si no se retira la vesícula biliar correctamente o a tiempo, la carne toma un regusto amargo como el de la fruta sin madurar. De ahí que conservar el delicioso sabor de la carne de este pez sea una de las muestras más claras de las dotes culinarias de un verdadero chef.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131023.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041601', 'genshin-impact', 'Pez hacha corriente', 'Common Axehead Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez con una forma única que guarda cierta relación de parentesco con los marlines. Una vez, unos biólogos bromearon con que los marlines habían elegido un “vientre en forma de hacha”, mientras que los peces hacha habían elegido una “cabeza en forma de hacha”.
Sin embargo, exceptuando su forma tan particular, su subespecie más numerosa no tiene ninguna otra característica especial, por lo que no sería exagerado decir que es el representante más “común y corriente” de Nod Krai.
Según las leyendas de las tabernas de la Villa Nasha, fijándose en las propiedades comunes de los peces hacha corrientes, algunos pescadores entrenan a determinados individuos que parecen más inteligentes para que, con sus espaldas en forma de hacha, corten el sedal de los competidores.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131046.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041603', 'genshin-impact', 'Pez hacha ferrocandente', 'Blazing Axehead Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez con una forma única que guarda cierta relación de parentesco con los marlines. Una vez, unos biólogos bromearon con que los marlines habían elegido un “vientre en forma de hacha”, mientras que los peces hacha habían elegido una “cabeza en forma de hacha”.
Este individuo tan especial tiene una espalda de un color tan candente como un hierro de marcar, y es muy raro de ver en Nod Krai. Dicen que, cuando alguien provoca la ira de la naturaleza mientras navega en barco, este tipo de pez hacha aparece de repente para destrozar la embarcación con su espalda ardiente y hacer que los malvados naufraguen y se ahoguen en el agua. Por esta razón, los pescadores que tienen la suerte de pescarlos muestran un gran respeto hacia los peces hacha ferrocandentes, de manera que, o bien los vuelven a poner en libertad, o bien los crían con mucho cuidado en peceras de lo más lujosas.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131048.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041602', 'genshin-impact', 'Pez hacha glacial', 'Frosted Axehead Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez con una forma única que guarda cierta relación de parentesco con los marlines. Una vez, unos biólogos bromearon con que los marlines habían elegido un “vientre en forma de hacha”, mientras que los peces hacha habían elegido una “cabeza en forma de hacha”.
Hay unos peces hacha con una espalda de color morado azulado que los pescadores comunes confundían con “témpanos de hielo procedentes de los mares del norte”. Los consideraban muy valiosos y los criaban en aguas a una temperatura cercana al punto de congelación. En realidad, su particular color se debe a sus hábitos alimenticios, distintos a los de los peces hacha corrientes. Si uno quisiera estudiar la cadena de transmisión de nutrientes del agua, este tipo de pez sería un excelente objeto de estudio.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131047.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041302', 'genshin-impact', 'Pez luna arrebol', 'Dusk Sunfish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de tamaño mediano y forma plana, conocido como la criatura más difícil de hacer enojar de todas las aguas de Natlan. Como tienen la costumbre de comerse cualquier cosa que se encuentran, son unos limpiadores de aguas natos muy apreciados por todo el mundo.
Según algunas historias populares, el color anaranjado y azul claro de estos peces luna se debe a que “se bebieron el arrebol del crepúsculo”, y todos sabemos lo apreciados que son en Natlan el sol y las llamas. Esta historia es considerada como el “epítome de la belleza poética de Natlan” según los autores de Liyue y Fontaine.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131042.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041301', 'genshin-impact', 'Pez luna limpiamareas', 'Greenwave Sunfish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de tamaño mediano y forma plana, conocido como la criatura más difícil de hacer enojar de todas las aguas de Natlan. Como tienen la costumbre de comerse cualquier cosa que se encuentran, son unos limpiadores de aguas natos muy apreciados por todo el mundo.
Dicen que, hace mucho tiempo, los peces luna limpiamareas vivían en aguas con un exceso de nutrientes, y cuya superficie estaba infestada de algas flotantes, de modo que sirvieron para controlar la sobrepoblación de dichas algas. De hecho, si hoy en día las aguas del Pueblo de los Manantiales son tan azules, en parte es gracias a estos peces.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131041.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041203', 'genshin-impact', 'Pez magmatorrencial', 'Magma Rapidfighting Fish', 'fauna', 'normal', 'Animales acuáticos', 'Un anfibio que se llama “pez”, pero que en realidad no lo es. Tiene una cabeza plana con forma de daga, como si estuviera preparado para luchar en cualquier momento contra sus depredadores. Sin embargo, en realidad es muy dócil y no se le da bien combatir, de modo que su cabeza le es útil para reducir la resistencia del agua al nadar en ríos. Gracias a ello, es capaz de nadar velozmente contra rápidos torrentes de agua, de ahí que su nombre sea “pez torrencial”.
Esta variedad de pez torrencial vive en el flogisto líquido y tiene una piel extremadamente dura que le permite aguantar muy bien las altas temperaturas, lo que le ha hecho ganarse el sobrenombre de “pez imposible de hacer a la parrilla”. A pesar de este título, la mayoría de los aficionados a la pesca no atrapan peces magmatorrenciales para cocinarlos, sino para cuidarlos y alimentarlos con mucho cariño como peces ornamentales.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131040.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040501', 'genshin-impact', 'Pez mariposa marrón', 'Brown Shirakodai', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie grácil y elegante del pez mariposa. Tiene una aleta dorsal muy bonita y la llaman “reina de los mares”.
Su cuerpo luce motivos de colores terrosos y su temperamento es tan firme como la roca. Pero a veces se exceden y se quedan quietos en el fondo sin moverse ni un milímetro, como una piedra, lo que lleva a los compradores a pensar que compraron un viejo pez moribundo.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131013.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040503', 'genshin-impact', 'Pez mariposa verdoso', 'Tea-Colored Shirakodai', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie grácil y elegante del pez mariposa. Tiene una aleta dorsal muy bonita y la llaman “reina de los mares”.
El cuerpo de este pez con curiosidad por todas las cosas luce motivos de color verdoso. Lamentablemente, su método para expresar interés es morder el objeto que le atrae. Esta acción, sin malicia en sí misma, ha puesto en aprietos a esta especie multitud de veces.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131015.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040502', 'genshin-impact', 'Pez mariposa violeta', 'Purple Shirakodai', 'fauna', 'normal', 'Animales acuáticos', 'Una subespecie grácil y elegante del pez mariposa. Tiene una aleta dorsal muy bonita y la llaman “reina de los mares”.
Su cuerpo luce motivos de color violeta y le gusta nadar en bancos con sus compañeros para defenderse de los peligros y de los depredadores. Pero una vez que los pescadores se dieron cuenta de esto, descubrieron que lo único que tenían que hacer era atraer a un pez a su trampa y todos los demás irían detrás.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131014.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041801', 'genshin-impact', 'Pez ojobrillante cieloazul', 'Azuregaze Crystal-Eye', 'fauna', 'normal', 'Animales acuáticos', 'Un pez con un aspecto muy llamativo y una cabeza traslúcida y brillante como el cristal. Suele deambular por las aguas de Nod Krai. Los que son de color azul recuerdan a un cielo despejado, de ahí que se los conozca como “cieloazul”.
Según los estudios realizados, la cabeza de estos peces está llena de un líquido protector y sus ojos principales se encuentran en ella, lo que les permite ver en todas direcciones y tener una gran capacidad de observación. Sin embargo, algunos animales suelen pensar que los dos lados de su boca son sus ojos cerrados y que siempre están durmiendo.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131051.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041802', 'genshin-impact', 'Pez ojobrillante nocturno', 'Nightgaze Crystal-Eye', 'fauna', 'normal', 'Animales acuáticos', 'Un pez con un aspecto muy llamativo y una cabeza traslúcida y brillante como el cristal. Suele deambular por las aguas de Nod Krai. Los que son de color oscuro recuerdan a una noche sin estrellas, de ahí que se los conozca como “nocturnos”.
Según los estudios realizados, la cabeza de estos peces está llena de un líquido protector y sus ojos principales se encuentran en ella, lo que les permite ver en todas direcciones y tener una gran capacidad de observación. Gracias al extraordinario flujo luminoso que les proporciona su cuerpo, los peces ojobrillantes nocturnos se han acostumbrado a las aguas muy profundas u oscuras, lo que les ha dotado de una mejor visión nocturna que otras especies acuáticas. De hecho, incluso ayudan a otros animales a enfrentarse a toda clase de peligros.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131052.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040903', 'genshin-impact', 'Pez olalabarda', 'Streaming Axe Marlin', 'fauna', 'normal', 'Animales acuáticos', 'Pariente lejano del pez mariposa, este pez posee un esqueleto de forma curvilínea. Cuenta la leyenda que el primer pescador que atrapó uno de estos peces lo hizo enganchando la caña al extremo de la aleta caudal del pez, y descubrió así que la forma resultante se parecía a la de una lanza. De ahí que en su nombre tenga la palabra “alabarda”, algo que resultó tan descriptivo que no tardó en extenderse más que su nombre científico: “mariposanzuelo”.
Se rumorea que el pez olalabarda de Fontaine llegó en realidad desde Sumeru y, a diferencia de sus parientes en dicha nación, tiene un carácter mucho más tenaz y es capaz de sobrevivir durante largos periodos de tiempo en entornos adversos o llevar a cabo largas travesías como si de un barco comerciante se tratara. Por eso, algunos marineros lo consideran un símbolo de valor y paciencia.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131029.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041402', 'genshin-impact', 'Pez unicornio escualiforme', 'Pseudoshark Unihornfish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de un solo cuerno. Su forma redonda y la elasticidad de su abdomen lo hacen comparable a un globo. De hecho, en su interior tiene una vejiga natatoria que es como un globo.
Los peces unicornio flogimiméticos cuentan con pigmentos muy valiosos para los aficionados a las pintadas, pero como solo sobreviven en entornos con flogisto líquido, la Alianza de las Pintadas empezó a explorar la posibilidad de criarlos en aguas normales. Por ello, el ex-ex-expresidente de la alianza invirtió una gran cantidad de dinero para importar mecapeces de Fontaine y, aprovechando la tecnología de los mecarreparadores, desarrolló un mecanismo de simulación ecológica con un sistema interno de recolección de datos para observarlos y estudiarlos. Sin embargo, los resultados fueron decepcionantes y, tras salir del entorno de flogisto líquido, los cuernos de cristal de los peces unicornio dejaron de brillar como el fuego, por lo que el plan fracasó.
Por fortuna, como desde la superficie estos peces mecánicos parecen tener una aleta de tiburón, el Pueblo de los Manantiales le compró una buena cantidad al Gremio de Pescadores de Natlan y los usó para proporcionar una experiencia segura y emocionante a los turistas surfistas, y también para asustar a los maleantes de algunas zonas acuáticas gracias a su forma de escuálidos.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131044.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041401', 'genshin-impact', 'Pez unicornio flogimimético', 'Phony Phlogiston Unihornfish', 'fauna', 'normal', 'Animales acuáticos', 'Un pez de un solo cuerno. Su forma redonda y la elasticidad de su abdomen lo hacen comparable a un globo.
El cuerno de cristal de su cabeza tiene características similares al flogisto sólido. Sin embargo, según algunos estudios, cuando estos peces aún están en periodo de incubación, sus cuernos son traslúcidos como el cristal. Tras vivir durante mucho tiempo en el flogisto líquido, el contacto constante con sustancias de diversos colores les da su color actual, lo que les ha hecho ganarse el gracioso sobrenombre de “flogimiméticos”.
El cristal flogimimético del cuerno de los peces unicornio se va desprendiendo a lo largo de los años a medida que crece. De hecho, los fragmentos que caen son un pigmento extremadamente valioso, de modo que los aficionados a las pintadas lo consideran el “color del fuego”.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131043.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030705', 'genshin-impact', 'Pichón colabanico burdeos', 'Magenta Fantail Pigeon', 'fauna', 'normal', 'Aves', 'El pichón colabanico burdeos es pariente cercano de la paloma. Tiene un porte elegante y, aunque se le puede entrenar para entregar mensajes a gran distancia, muy poca gente lo cría con ese fin.
Esta ave tiene un característico plumaje rojizo en la cola en forma de abanico, la cual se asemeja a un corazón. Por eso, los poetas lo considera un símbolo indiscutible del amor. En la práctica, este plumaje carmín le sirve para ahuyentar a sus enemigos naturales y no guarda relación alguna con el cortejo.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fantail_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030706', 'genshin-impact', 'Pichón colabanico esmeralda', 'Viridian Fantail Pigeon', 'fauna', 'normal', 'Aves', 'El pichón colabanico esmeralda es pariente cercano de la paloma. Tiene un porte elegante y, aunque se le puede entrenar para entregar mensajes a gran distancia, muy poca gente lo cría con ese fin.
Esta ave tiene un característico plumaje viridiscente en la cola en forma de abanico. Tiene una personalidad combativa y a menudo se lo ha confundido con una cría del Espantohongo Plumaverde por los extranjeros que ya habían visitado Sumeru. Pero lo cierto es que no guardan relación el uno con el otro.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fantail_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030401', 'genshin-impact', 'Pinzón carmesí', 'Crimson Finch', 'fauna', 'normal', 'Aves', 'Un pajarito ruidoso que se puede encontrar por todo Teyvat.
Estos pájaros tienen plumas de un vivo color rojo con las que atraen a los miembros del sexo opuesto. Por desgracia, este color también atrae la atención de los depredadores, lo que convierte a esta pequeña ave en uno de los principales alimentos de los carnívoros de Teyvat...', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tit_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030708', 'genshin-impact', 'Pinzón crestiazul', 'Bluecrown Finch', 'fauna', 'normal', 'Aves', 'Un pequeño pájaro cantor muy común en Fontaine. Es un placer disfrutar de sus alegres gorjeos.
Se dice que los pinzones crestiazules son particularmente sensibles al mundo que los rodea y están dispuestos a abandonar sus nidos a la menor señal de peligro que perciban en el aire. Quizá por eso las fábulas los describen como animales más bien temerosos, a menudo portadores de desastres. Ver a un pinzón crestiazul salir volando a toda velocidad es signo inequívoco de que una calamidad está por llegar.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Larvivora_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030707', 'genshin-impact', 'Pinzón crestirrojo', 'Redcrown Finch', 'fauna', 'normal', 'Aves', 'Un pequeño pájaro cantor muy común en Fontaine. Es un placer disfrutar de sus alegres gorjeos.
A pesar de su adorable apariencia, el pinzón crestirrojo es un hábil luchador que, con frecuencia, ataca a los pájaros con los que se cruza. Sin embargo, cuando son pequeños y aún no tienen su plumaje en forma de cresta, carecen de esa faceta agresiva.
Por eso, desde antaño se ha considerado al pinzón crestirrojo un símbolo de valor. De hecho, a los pinzones crestirrojos que ya poseen su particular plumaje carmín se los considera guerreros dispuestos incluso a enfrentarse al destino.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Larvivora_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030402', 'genshin-impact', 'Pinzón dorado', 'Golden Finch', 'fauna', 'normal', 'Aves', 'Un pajarito ruidoso que se puede encontrar por todo Teyvat.
Posee un brillante plumaje dorado que reluce bajo el sol. A los niños les gusta atraparlos para tenerlos como mascotas, pero no se adaptan bien a la vida con los humanos y aprovechan cualquier ocasión para escapar.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tit_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030411', 'genshin-impact', 'Pinzón plumanaranja ancestral', 'Ancient Scarlet-Plume Finch', 'fauna', 'normal', 'Aves', 'Un pinzón ancestral con plumas como llamas.
Aunque no hay pruebas que lo demuestren, los amantes de los pinzones siempre han sostenido que, en el pasado, tenían plumas más largas y eran más grandes. Este pinzón ancestral, que ha sobrevivido hasta hoy gracias a su entorno aislado, podría ser la prueba que necesitan.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tit_05.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030403', 'genshin-impact', 'Pinzón polar', 'Snow Finch', 'fauna', 'normal', 'Aves', 'Un pajarito ruidoso que se puede encontrar por todo Teyvat.
Estas criaturas blancas y diminutas disfrutan en la nieve y el hielo. Están bien adaptadas para vivir en climas muy fríos y son muy sensibles a los cambios de temperatura. En zonas cálidas se vuelven lentos y torpes y es fácil atraparlos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tit_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28030404', 'genshin-impact', 'Pinzón turquesa', 'Emerald Finch', 'fauna', 'normal', 'Aves', 'Un pajarito ruidoso que se puede encontrar por todo Teyvat.
Este pinzón tiene un plumaje de color azul turquesa y fue el primer pájaro utilizado como “canario” por los mineros, ya que su estado de salud se puede determinar fácilmente observando el lustre de sus plumas. Hoy en día, los mineros siguen llevando estos pájaros a las minas, pero ya no se preocupan tanto por el color de sus plumas.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tit_04.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040305', 'genshin-impact', 'Pisanieves', 'Snowstrider', 'fauna', 'normal', 'Animales acuáticos', 'Un espinoso poco común que habita en regiones frías y montañosas. Quizás las bajas temperaturas son el motivo de que estos espinosos tengan un temperamento más calmado que sus parientes. Esta especie adora el frío y, aunque puede sobrevivir en aguas más cálidas, alejarse de las aguas gélidas supone un duro golpe: se deprime y se niegan a reproducirse.
“No son una captura recomendable”, dice el capítulo de los pisanieves del «Manual de pesca con caña».', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131010.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28060501', 'genshin-impact', 'Plaquidermo de carga', 'Desert Sumpter Beast', 'fauna', 'normal', 'Animales terrestres', 'Un animal de carga es el mejor amigo del hombre. Estas pacíficas criaturas resultan indispensables en el transporte de mercancías.
Los animales de carga son capaces de adaptarse a todo tipo de hábitats naturales. Antes de que los comerciantes pusieran su mira en ellos, los animales de carga ya llevaban largo tiempo siendo un apoyo constante para las familias del desierto.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Megamoth_Desert.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28051101', 'genshin-impact', 'Polilla alaetérea', 'Etherwing Moth', 'fauna', 'normal', 'Otros', 'Una extraña criatura que emite un sagrado resplandor dorado y flota como una polilla a través del misterioso intersticio.
Cuenta la leyenda que la polilla alaetérea nació de las plumas caídas de ángeles rebeldes que una vez desafiaron al señor de los cielos. Sin embargo, esto no explica por qué aparecen en el territorio del estancamiento eterno.
Quizás, a ojos de cierta divinidad, estas criaturas tienen valor como testimonio del castigo de los pecadores y merecen ser preservadas.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Wisp_PlumeMoth_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28010301', 'genshin-impact', 'Rana', 'Frog', 'fauna', 'normal', 'Otros', 'Una ranita que vive en zonas húmedas.
Son animales muy comunes en las zonas donde hay agua. Su piel produce una sustancia viscosa con propiedades medicinales.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Frog_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28010304', 'genshin-impact', 'Rana arbórea', 'Forest Tree Frog', 'fauna', 'normal', 'Otros', 'Una ranita que vive en zonas húmedas.
Son animales muy comunes en las zonas donde hay agua. Su piel produce una sustancia viscosa con propiedades medicinales. Las ranas arbóreas se han adaptado a la vida en los bosques.
Algunos afirman que este tipo de rana es capaz de planear entre los árboles, y los investigadores afirman que es un fenómeno parecido al que tiene lugar al usar un planeador.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Frog_04.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28010303', 'genshin-impact', 'Rana azul', 'Blue Frog', 'fauna', 'normal', 'Otros', 'Una ranita que vive en zonas húmedas.
Son animales muy comunes en las zonas donde hay agua. Su piel produce una sustancia viscosa con propiedades medicinales. Las ranas azules prefieren las aguas más puras.
Según se ha observado, varias especies de ranas se vuelven verdes cuando la sustancia viscosa que hay en su piel se seca. La teoría más aceptada es que esto es un mecanismo de supervivencia que transforma su capa exterior para ayudarlas a retener la humedad de su cuerpo.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Frog_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28010302', 'genshin-impact', 'Rana de barro', 'Mud Frog', 'fauna', 'normal', 'Otros', 'Una ranita que vive en zonas húmedas.
Son animales muy comunes en las zonas donde hay agua. Su piel produce una sustancia viscosa con propiedades medicinales. El color ocre de estas ranas hace que se camuflen más fácilmente en las orillas.
En Fontaine, a los ladrones difíciles de atrapar y a los criminales que escapan de su justa sentencia los llaman “ranas de barro en un bote de mantequilla”.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Frog_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040701', 'genshin-impact', 'Raya divda', 'Divda Ray', 'fauna', 'normal', 'Animales acuáticos', 'Una misteriosa raya que, en el pasado, se pensaba que era un ser fantástico. Solo hay registros de ellas en algunas antiguas pinturas de la Isla Watatsumi. Su verdadero aspecto por fin se ha descubierto en el presente gracias a la reapertura de las profundidades del océano.
Dicen que el color de su cuerpo cambia con el tiempo, y que de pequeñas tienen un color dorado claro y tan brillante como el sol. En las pinturas antiguas, a las rayas en esta etapa de la vida se las llamaba “divda”, lo cual significa “el final de la inocencia”.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131021.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040703', 'genshin-impact', 'Raya flotante', 'Floating Ray', 'fauna', 'normal', 'Animales acuáticos', 'Una criatura extremadamente rara que vuela por el cielo.
Se dice que este tipo de raya solía cazar a sus presas en las oscuras profundidades del océano utilizando partículas fluorescentes y elementales para atraerlas.
Las leyendas también cuentan que acabaron en Enkanomiya porque confundieron a la gran serpiente cubierta de coral con el lecho marino en el que habitaban...', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fishable_Ray_Stellamarisidae_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040702', 'genshin-impact', 'Raya formalo', 'Formalo Ray', 'fauna', 'normal', 'Animales acuáticos', 'Una misteriosa raya que, en el pasado, se pensaba que era un ser fantástico. Solo hay registros de ellas en algunas antiguas pinturas de la Isla Watatsumi. Su verdadero aspecto por fin se ha descubierto en el presente gracias a la reapertura de las profundidades del océano.
Dicen que el color de su cuerpo cambia con el tiempo, y que de pequeñas tienen un color dorado claro y tan brillante como el sol. Cuando son adultas, este color se oscurece y sus aletas se cubren de un color violeta profundo. En las pinturas antiguas, a las rayas en esta etapa de la vida se las llamaba “formalo”, lo cual significa “boca avariciosa”.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131022.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020304', 'genshin-impact', 'Rey Jabalí de las Nieves', 'Great Snowboar King', 'fauna', 'normal', 'Animales terrestres', 'Un “rey” que habita en zonas cubiertas por el hielo y la nieve, esperando a que sus parientes congelados lo devuelvan a la vida.
Antiguamente, había una leyenda entre los cazadores: cuando la tierra congelada reviva y la paz de las cuevas se vea interrumpida por visitantes inesperados, el legendario rey de los jabalíes despertará de su letargo, romperá las cadenas de hielo que lo aprisionan y dará una buena lección a los intrusos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Boar_03.png', '[]'::jsonb, '[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":30},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":30},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, null),
  ('gi-enemy-28022901', 'genshin-impact', 'Rinoceronte cuernorrobusto', 'Blunthorn Rhino', 'fauna', 'normal', 'Animales terrestres', 'Un pariente lejano de los diplocerontes de Natlan, aunque tal afirmación resulte difícil de creer a primera vista...
Los rinocerontes cuernorrobustos están cubiertos casi al completo por un estrato córneo endurecido, y la sección más dura de su lomo puede incluso reaccionar al kuuvahki.
Suelen ser criaturas amigables, pero si se sienten amenazadas, lucharán obcecadamente hasta el final. Llegado el momento, sus atacantes descubrirán que no son ni tan pesados ni tan torpes como su apariencia podría indicar.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_NodRhino_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020413', 'genshin-impact', 'Sabueso ambarino', 'Amber Hunting Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo de las personas!
Una raza de perro característica por su pelaje marrón y dorado. Es la raza más pura de perros cazadores de Fontaine. Este animal es extremadamente leal a su dueño y posee un desarrollado sentido del olfato que le permite perseguir tanto presas como criminales.
También se comenta que son diestros en el agua, aunque son pocos los que han llegado ver a uno de estos perros nadando. De hecho, el origen de esta teoría radica en una anécdota publicada una vez por «El Pájaro de Vapor».', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Dog_DropEar_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020411', 'genshin-impact', 'Sabueso castaño', 'Chestnut Hunting Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo de las personas!
Un perro con pelaje tricolor, resultado de la mezcla de varias razas distintas. Tiene un cuerpo fuerte y es considerablemente inteligente, por lo que la gente suele criarlos como mascotas y entrenarlos para que ayuden en diversas tareas.
Sin embargo, se rumorea que este perro se descontrola cuando no recibe órdenes de su dueño y que su glotonería le lleva a aceptar recompensas de extraños sin miramiento alguno. Es esta clase de comportamiento la que hace que a menudo padezcan problemas estomacales y que causa verdaderos quebraderos de cabeza a sus dueños.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Dog_DropEar_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020412', 'genshin-impact', 'Sabueso cenizo', 'Glittergray Hunting Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo de las personas!
Esta raza de sabuesos de precioso pelaje blanco cenizo es el que mejor relación mantiene con las gentes del interior del continente. Posee un sorprendente aguante que le permite soportar largas travesías por la naturaleza.
El mayor problema de este canino es que su pelaje se ensucia a la mínima de cambio, por lo que sus dueños pasan buena parte del tiempo bañándolos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Dog_DropEar_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020404', 'genshin-impact', 'Sabueso de lomo negro', 'Black-Back Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo del hombre!
Se dice que son los descendientes de los sabuesos de caza que criaban los aristócratas de Mondstadt. En la actualidad se han extendido por todo Teyvat y son apreciados por su lealtad y carácter amistoso, más que por sus orígenes nobles. Igual que los arrogantes aristócratas de Mondstadt fueron sustituidos por los humildes y queridos Caballeros de Favonius.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_DogPrick_03.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020401', 'genshin-impact', 'Sabueso del Norte', 'Northland Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo del hombre!
Proceden de una especie canina de las lejanas tierras del norte y poseen un pelaje blanco y gris muy espeso. Resisten muy bien las bajas temperaturas y tienen un carácter alegre y sin complicaciones. Bajo ningún concepto los dejes a solas con una ardilla.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_DogPrick_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020402', 'genshin-impact', 'Sabueso guardabosques', 'Forest-Patrol Hound', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo del hombre!
Fueron domesticados para convertirlos en compañeros de los cazadores de las montañas, pero también son buenos guardianes en las casas de las ciudades. Son unos perros muy amistosos e inteligentes, y muy adecuados para los niños.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_DogPrick_04.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28040506', 'genshin-impact', 'Selénido', 'Moonfin', 'fauna', 'normal', 'Animales acuáticos', 'Un tipo de pez mariposa muy valioso capaz de emitir luz en las profundidades del oscuro océano. Le gusta vivir en grupos y, al juntarse con otros, se asemejan a una brillante luna sumergida en el mar. Es el antecesor del leviatán lunar. Debido a estas características, muchos seres marinos atraídos por la luz también se sienten atraídos por el selénido. En cierto sentido, este pez es capaz de guiar a las personas que están sumidas en la oscuridad.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131018.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020403', 'genshin-impact', 'Shiba', 'Shiba', 'fauna', 'normal', 'Animales terrestres', '¡El mejor amigo del hombre!
Cuenta la leyenda que era la raza favorita de los Shogun de Inazuma y se extendió por las Siete Naciones a través de las prósperas rutas comerciales, hasta convertirse en la mascota más popular en todo Teyvat. Es un perro fiel e inteligente, muy apropiado para vigilar la casa y hacer compañía a la familia. Se dice que en Inazuma todavía quedan algunos ninjas misteriosos que adiestran a estos animales para que sean “perros ninja”.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_DogPrick_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021601', 'genshin-impact', 'Suaverizo', 'Fluffahog', 'fauna', 'normal', 'Animales terrestres', 'Un animal cuyo cuerpo está cubierto de espinas, a excepción de su vientre, suave y blandito.
Los suaverizos son dóciles, les encanta dormir y se les da muy bien utilizar hierba y ramas para construir madrigueras ocultas en las que disfrutar de un sueño cálido y placentero durante el invierno. Si alguien descubre su madriguera, se hacen una bolita y se enfrentan al mundo con su duro caparazón, como si así pudieran defenderse de cualquier amenaza.
En los cuentos populares de Snezhnaya, el suaverizo es el animal más inteligente. Conoce recetas de hierbas medicinales mágicas, sabe cuál es el secreto para no envejecer e incluso entiende cómo abrir una cerradura sin llave.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Hedgehog_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020801', 'genshin-impact', 'Tanuki', 'Bake-Danuki', 'fauna', 'normal', 'Animales terrestres', 'Una criatura despreocupada por naturaleza que aparece y desaparece a su antojo, y cuyos conocimientos de magia son limitados. Hay algunos capaces de tomar forma de otros objetos, e incluso de humanos.
A pesar de que con frecuencia se asocian con una organización secreta perteneciente al shogunato, en realidad sus intenciones no son malas. Suelen gastarle bromas a los humanos por simple diversión.
Solo hay registros de un caso excepcional. Muchos años atrás, los tanuki del Bosque Chinju declararon una guerra, con el tanuki Ioroi como su líder. Al parecer la causa era la disputa del cabecilla con un kitsune. Al final, como resultado de este evento, la mayoría de los tanuki fueron sellados en estatuillas de piedra.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Inu_Tanuki_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021401', 'genshin-impact', 'Tejón mantomelena', 'Chic Badger', 'fauna', 'normal', 'Animales terrestres', 'Su nombre se debe a los dos largos mechones de melena que se extienden desde sus hombros. Su melena emite un suave brillo cuando se ve afectado por el kuuvahki, como si el animal poseyera una capa hecha de luz de luna.
Puede que los tejones mantomelena resulten adorables cuando retozan en la tierra, pero son cazadores excepcionales. Son capaces de esprintar a una velocidad sorprendente, por lo que cualquier cosa que los enfurezca lo tendrá difícil para escapar.
Han desarrollado el hábito de almacenar comida para todo el invierno, e impregnan estas provisiones con secreciones de sus glándulas odoríferas para impedir que sus alijos de suministros sean objeto de robo. Por lo tanto, si alguien afirmara haber sobrevivido gracias a las provisiones de un tejón mantomelena, estaría mintiendo o deben estar muy por encima de la cadena trófica, al menos en cuanto a fuerza de voluntad se refiere...', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Wolverine_01_N.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021404', 'genshin-impact', 'Tejón peludo', 'Fuzzbadger', 'fauna', 'normal', 'Animales terrestres', 'Un animal que habita en el interior de Snezhnaya y pariente cercano del tejón mantomelena.
El tejón peludo está cubierto de un pelaje largo, suave y denso que le permite desplazarse con total libertad incluso en las regiones más frías.
A pesar de su suave apariencia, posee un temperamento feroz y jamás se acobarda ante oponentes de mayor tamaño que él. La ley de supervivencia en las llanuras nevadas es: no te adentres a la ligera en el territorio de un tejón peludo, y mucho menos intentes quitarle su comida. De lo contrario, sacará sus afiladas garras y dará una buena y veloz lección al intruso.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Wolverine_04.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041702', 'genshin-impact', 'Tibuferoz iridiscente', 'Neon Mauler Shark', 'fauna', 'normal', 'Animales acuáticos', 'Un depredador que se mueve por las aguas de Nod Krai, así como un pez carnívoro especialmente agresivo. Antes solía meterse cualquier cosa en la boca y lo aplastaba con sus grandes fauces, pero ahora se ha vuelto más dócil debido a que muchos de ellos ingirieron por error objetos aún no detonados desechados por la Oficina de Diseño Experimental Kuuvahki.
Tras ver lo que les ocurría a los tibuferoces normales, algunos individuos más inteligentes aprendieron a camuflarse, de manera que empezaron a ingerir alimentos no perjudiciales de colores y desarrollaron unos patrones que recuerdan a un cartel luminoso. Así, cuando acechan desde debajo del agua sin moverse, los pescadores de Nod Krai los confunden con basura marina... ¿O tal vez no?
Por desgracia, la respuesta es que no. Los carteles luminosos son demasiado valiosos como para que los comerciantes los tiren así como así... Sin embargo, estos tibuferoces especiales en realidad son bastante suertudos, ya que, gracias a su particular aspecto exterior, algunos pescadores deciden protegerlos y cuidar de ellos, lo que por fin les da la oportunidad de volver a comer carne.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131050.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28041701', 'genshin-impact', 'Tibuferoz vegetariano', 'Veggie Mauler Shark', 'fauna', 'normal', 'Animales acuáticos', 'Un depredador que se mueve por las aguas de Nod Krai, así como un pez carnívoro especialmente agresivo. Antes solía meterse cualquier cosa en la boca y lo aplastaba con sus grandes fauces, pero ahora se ha vuelto más dócil debido a que muchos de ellos ingirieron por error objetos aún no detonados desechados por la Oficina de Diseño Experimental Kuuvahki.
Pero la cosa no acaba ahí, ya que los pescadores saludan a estos tiburones usando toda clase de armas para evitar que se coman su potencial pesca, razón por la cual han evolucionado hasta convertirse en animales omnívoros. Ahora comen lo que se encuentren, y hasta los hay que se hacen vegetarianos durante años y no vuelven a comer carne, aunque no por ello les faltan los nutrientes que necesitan.', 'https://gi.yatta.moe/assets/UI/UI_ItemIcon_131049.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021003', 'genshin-impact', 'Tortuga brillocaparazón ancestral', 'Ancient Glazeback Turtle', 'fauna', 'normal', 'Animales terrestres', 'Un reptil con un caparazón duro que contiene fragmentos cristalizados de flogisto sólido.
Es similar a otros reptiles de Teyvat, pero como vive en zonas ricas en flogisto, su caparazón contiene muchas cristalizaciones sólidas de la misma naturaleza. Se dice que una vez apareció un ejemplar fuera de un volcán a causa de su erupción. Tras estudiarlo, algunos académicos llegaron a creer que su evolución era más lenta que la de otras tortugas.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tortoise_03.png', '[]'::jsonb, '[{"elemento":"Físico","valor":null,"inmune":true},{"elemento":"Pyro","valor":null,"inmune":true},{"elemento":"Hydro","valor":null,"inmune":true},{"elemento":"Anemo","valor":null,"inmune":true},{"elemento":"Electro","valor":null,"inmune":true},{"elemento":"Dendro","valor":null,"inmune":true},{"elemento":"Cryo","valor":null,"inmune":true},{"elemento":"Geo","valor":null,"inmune":true}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021002', 'genshin-impact', 'Tortuga litojade', 'Jadestone Turtle', 'fauna', 'normal', 'Animales terrestres', 'Un réptil con un grueso caparazón.
Al igual que sus otros parientes de Teyvat, es de carácter dócil y movimientos lentos. Tal vez precisamente por esa extrema docilidad y lentitud no le importe mucho que su caparazón quede cubierto de rocas de montañas en zonas donde abunda el elemento Geo.
Cuenta la leyenda que, en un pasado muy remoto, los ancestros de Chenyu vieron una tortuga gigante aún más grande que una montaña, a la cual llamaron “Gui”. Ya no se puede corroborar la veracidad de esta leyenda, pero sí es cierto que las tortugas litojade pueden crecer hasta convertirse en criaturas robustas y enormes.
Como todo el mundo, estas tortugas también tienen sus problemas; y es que la excesiva acumulación del elemento Geo en sus caparazones les provocan unos picores insoportables. Si alguien de buen corazón la ayuda a deshacerse de esa molestia y le quita el jade del caparazón, las apacibles tortugas litojade se lo agradecerán.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tortoise_02.png', '[]'::jsonb, '[{"elemento":"Físico","valor":null,"inmune":true},{"elemento":"Pyro","valor":null,"inmune":true},{"elemento":"Hydro","valor":null,"inmune":true},{"elemento":"Anemo","valor":null,"inmune":true},{"elemento":"Electro","valor":null,"inmune":true},{"elemento":"Dendro","valor":null,"inmune":true},{"elemento":"Cryo","valor":null,"inmune":true},{"elemento":"Geo","valor":null,"inmune":true}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28021001', 'genshin-impact', 'Tortuga ondulada', 'Tent Tortoise', 'fauna', 'normal', 'Animales terrestres', 'Un reptil con un robusto caparazón.
Tiene un carácter amable y camina con lentitud. Como goza de una gran longevidad, algunas personas lo consideran un símbolo de buena suerte y sabiduría. Sin embargo, al ser tan amable y lento, otras personas lo usan como metáfora para meterse con los demás. Pero esto a la tortuga ondulada le da igual, pues ella se dedica a caminar tranquilamente por el mundo y le trae sin cuidado el lenguaje de los humanos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Tortoise_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":null,"inmune":true},{"elemento":"Pyro","valor":null,"inmune":true},{"elemento":"Hydro","valor":null,"inmune":true},{"elemento":"Anemo","valor":null,"inmune":true},{"elemento":"Electro","valor":null,"inmune":true},{"elemento":"Dendro","valor":null,"inmune":true},{"elemento":"Cryo","valor":null,"inmune":true},{"elemento":"Geo","valor":null,"inmune":true}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":null,"inmune":true},{"elemento":"Pyro","valor":null,"inmune":true},{"elemento":"Hydro","valor":null,"inmune":true},{"elemento":"Anemo","valor":null,"inmune":true},{"elemento":"Electro","valor":null,"inmune":true},{"elemento":"Dendro","valor":null,"inmune":true},{"elemento":"Cryo","valor":null,"inmune":true},{"elemento":"Geo","valor":null,"inmune":true}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":50},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":70},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, null),
  ('gi-enemy-28050701', 'genshin-impact', 'Unidad de subdetección', 'Subdetection Unit', 'fauna', 'normal', 'Otros', 'Una pequeña unidad de detección fabricada por el Instituto de Ciencias de Fontaine que utiliza los nuevos componentes mecánicos y que, en un principio, se utilizaban para monitorizar diversos tipos de datos medioambientales.
Inicialmente, estas unidades eran gestionadas conjuntamente por el Departamento de Investigación y Desarrollo de Mecánica Avanzada y por el Departamento de Ecología y Control Medioambiental. El primero se encargaba de producir y desplegar los dispositivos, mientras que el segundo se encargaba de recopilar y cotejar los datos. Dado que este último se disolvió debido a un accidente experimental, el Instituto de Ciencias de Fontaine ahora solo se encarga de llevar a cabo la primera operación.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_BoltBug_MachinaIustitia_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28060601', 'genshin-impact', 'Yak de carga', 'Shaggy Sumpter Beast', 'fauna', 'normal', 'Animales terrestres', 'Un animal de carga es el mejor amigo del hombre. Estas pacíficas criaturas resultan indispensables en el transporte de mercancías.
En Sumeru, poseer numerosos animales de carga es uno de los más claros símbolos de riqueza. Es frecuente ver a grandes comerciantes y a Los Eremitas en compañía de grandes caravanas de animales de carga con las que no solo se suplen de todos los productos necesarios, sino que también les permiten cruzar tanto el desierto como el bosque.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Megamoth_Jungle.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020501', 'genshin-impact', 'Zafiro', 'Sapphire', 'fauna', 'normal', 'Animales terrestres', 'Un animal ágil e inteligente que posee un carácter orgulloso y una elegancia nata.
Estos gatos de pelaje blanco se llaman así por sus ojos azules y brillantes. A pesar de su elegancia, estos felinos tienen muy mal genio. Ten siempre a mano una buena cantidad de pescado seco y pomada para los arañazos.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Cat_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020701', 'genshin-impact', 'Zorro', 'Kitsune', 'fauna', 'normal', 'Animales terrestres', 'Una criatura ingeniosa y arrogante. En las leyendas populares son seres altamente inteligentes y con una memoria excelente.
Aunque algunos de estos seres desprecian al ser humano, están acostumbrados a convivir con ellos.
En el folclore de Inazuma, su origen se remonta muy atrás en la historia. De acuerdo a una leyenda, son los hijos de un descendiente de la gran Sacerdotisa Kitsune. Al desaparecer, los Kitsune Celestiales y Terrenales, más poderosos que ella, se convirtieron en piedra para aguardar a su retorno. En cambio, los kitsune perdieron la capacidad de hablar y sus habilidades mágicas con la disolución de su poder.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Vulpes_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020102', 'genshin-impact', 'Zorro carmesí', 'Crimson Fox', 'fauna', 'normal', 'Animales terrestres', 'Una criatura astuta que no se deja ver con facilidad. Según las creencias populares, posee una misteriosa sabiduría y una buena memoria.
Zorros de pequeño tamaño que se esconden entre los árboles y la hierba para esquivar la vista y las flechas de los cazadores.
En todas partes existen leyendas populares en las que aparecen zorros que han vivido muchos años y han acumulado una gran inteligencia, incluso hasta el punto de poseer poderes impensables. También hay historias sobre zorros capaces de tomar forma humana, como se relata en el popular libro infantil «El zorro en el mar de dientes de león».', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fox_02.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-28020101', 'genshin-impact', 'Zorro de nieve', 'Snow Fox', 'fauna', 'normal', 'Animales terrestres', 'Una criatura astuta que no se deja ver con facilidad. Según las creencias populares, posee una misteriosa sabiduría y una buena memoria.
Su pelaje es blanco y espeso para poder sobrevivir y camuflarse en la nieve. Al vivir en un entorno hostil, han desarrollado un olfato más agudo y siempre están alerta.', 'https://gi.yatta.moe/assets/UI/monster/UI_AnimalIcon_Fox_01.png', '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, null)
on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      name_en = excluded.name_en,
      category = excluded.category,
      rank = excluded.rank,
      faction = excluded.faction,
      description = excluded.description,
      image_url = excluded.image_url,
      weaknesses = excluded.weaknesses,
      resistances = excluded.resistances,
      variants = excluded.variants,
      skills = excluded.skills,
      drops = excluded.drops,
      updated_at = now();

-- Comprobacion
select category, rank, count(*) as enemigos, count(image_url) as con_icono
from public.enemies
where game_id = 'genshin-impact'
group by category, rank
order by category, rank;
